frappe.ui.form.on('Product Delivery', {
    validate: function(frm) {
        pd_calculate(frm);
        pd_refresh_summaries(frm);
    },

    stock_entry_type: function(frm) { frm.refresh(); },

    refresh: function(frm) {
        if (frm.is_new()) { return; }

        pd_refresh_summaries(frm);

        if (frm.doc.transfer_status === 'Transferred' && frm.doc.stock_entry) {
            frm.add_custom_button('View Stock Entry', function() {
                frappe.set_route('Form', 'Stock Entry', frm.doc.stock_entry);
            });

            frappe.db.count('Installation', { filters: { product_delivery: frm.doc.name } }).then(function(n) {
                if (n) { return; }

                frm.add_custom_button('Installation', function() {
                    var build = function(employee) {
                        frappe.model.with_doctype('Installation', function() {
                            var d = frappe.model.get_new_doc('Installation');
                            d.customer = frm.doc.customer;
                            d.company = frm.doc.company;
                            d.project = frm.doc.project;
                            d.product_delivery = frm.doc.name;
                            d.site_visit = frm.doc.site_visit;
                            d.sales_order = frm.doc.sales_order;
                            d.phone = frm.doc.phone;
                            d.contact_person = frm.doc.contact_person;
                            d.installation_address = frm.doc.delivery_address;
                            d.installation_status = 'Pending';
                            d.scheduled_date = frappe.datetime.get_today();
                            d.site_warehouse = frm.doc.target_warehouse;
                            d.return_warehouse = frm.doc.source_warehouse;
                            d.material_status = 'Pending';
                            d.assigned_to = employee;

                            var t_qty = 0;
                            (frm.doc.items || []).forEach(function(row) {
                                if (!row.is_stock_item) { return; }
                                var child = frappe.model.add_child(d, 'Installation Material', 'materials');
                                child.item_code = row.item_code;
                                child.item_name = row.item_name;
                                child.uom = row.uom;
                                child.transferred_qty = row.qty;
                                child.used_qty = 0;
                                child.balance_qty = row.qty;
                                child.rate = row.rate;
                                if (row.batch_no) { child.batch_no = row.batch_no; }
                                if (row.serial_no) { child.serial_no = row.serial_no; }
                                t_qty += flt(row.qty);
                            });
                            d.total_transferred_qty = t_qty;
                            d.total_used_qty = 0;
                            d.total_balance_qty = t_qty;

                            var vals = {
                                product_delivery: frm.doc.name,
                                project: frm.doc.project,
                                site_warehouse: frm.doc.target_warehouse,
                                return_warehouse: frm.doc.source_warehouse,
                                assigned_to: employee
                            };

                            frappe.set_route('Form', 'Installation', d.name);
                            setTimeout(function() {
                                if (cur_frm && cur_frm.doc && cur_frm.doc.doctype === 'Installation' && cur_frm.doc.name === d.name) {
                                    Object.keys(vals).forEach(function(k) {
                                        if (vals[k] && !cur_frm.doc[k]) { cur_frm.set_value(k, vals[k]); }
                                    });
                                    cur_frm.refresh_fields();
                                }
                            }, 600);
                        });
                    };

                    if (frm.doc.site_visit) {
                        frappe.db.get_value('Site Visit', frm.doc.site_visit, 'employee')
                            .then(function(r) { build(r && r.message ? r.message.employee : null); })
                            .catch(function() { build(null); });
                    } else {
                        build(null);
                    }
                }, 'Create');
            });
            return;
        }

        if (frm.doc.transfer_status === 'Pending' || frm.doc.transfer_status === 'Cancelled') {

            var is_transfer = (frm.doc.stock_entry_type !== 'Material Issue');
            var se_label = is_transfer ? 'Material Transfer' : 'Material Issue';

            frm.add_custom_button(se_label, function() {
                var stock_rows = (frm.doc.items || []).filter(function(r) {
                    return r.is_stock_item && flt(r.qty) > 0;
                });

                if (!stock_rows.length) {
                    frappe.msgprint('Add at least one stock item before creating the stock entry. Service items are not transferred.');
                    return;
                }
                if (!frm.doc.stock_entry_type) {
                    frappe.msgprint('Set a Purpose first.');
                    return;
                }
                if (!frm.doc.source_warehouse) {
                    frappe.msgprint('Set a Source Warehouse first.');
                    return;
                }
                if (is_transfer && !frm.doc.target_warehouse) {
                    frappe.msgprint('Set a Target Warehouse for a Material Transfer.');
                    return;
                }

                var errors = pd_tracking_errors(frm);
                if (errors.length) {
                    frappe.msgprint({
                        title: 'Serial / Batch selection incomplete',
                        indicator: 'red',
                        message: '<ul style="padding-left:18px;margin:0;"><li>' +
                                 errors.join('</li><li>') + '</li></ul>'
                    });
                    return;
                }

                var project_name = frm.doc.project;

                frappe.model.with_doctype('Stock Entry', function() {
                    var se = frappe.model.get_new_doc('Stock Entry');
                    se.stock_entry_type = frm.doc.stock_entry_type;
                    se.purpose = frm.doc.stock_entry_type;
                    se.company = frm.doc.company;
                    se.product_delivery = frm.doc.name;
                    se.project = project_name;
                    se.custom_projects = project_name;
                    se.from_warehouse = frm.doc.source_warehouse;
                    if (is_transfer) { se.to_warehouse = frm.doc.target_warehouse; }

                    stock_rows.forEach(function(row) {
                        var serials = pd_serial_list(row);
                        var allocs = (row.batch_allocation || []).filter(function(b) {
                            return b.batch_no && flt(b.qty) > 0;
                        });

                        var add_row = function(q, batch_no, serial_chunk) {
                            var d = frappe.model.add_child(se, 'Stock Entry Detail', 'items');
                            d.item_code = row.item_code;
                            d.qty = q;
                            d.uom = row.uom;
                            d.stock_uom = row.uom;
                            d.conversion_factor = 1;
                            d.s_warehouse = row.s_warehouse || frm.doc.source_warehouse;
                            if (is_transfer) {
                                d.t_warehouse = row.t_warehouse || frm.doc.target_warehouse;
                            }
                            d.project = project_name;

                            // Hand the selection to ERPNext as plain serial/batch
                            // fields. ERPNext builds the Serial and Batch Bundle
                            // itself when the Stock Entry is submitted.
                            if (batch_no || (serial_chunk && serial_chunk.length)) {
                                d.use_serial_batch_fields = 1;
                                if (batch_no) { d.batch_no = batch_no; }
                                if (serial_chunk && serial_chunk.length) {
                                    d.serial_no = serial_chunk.join('\n');
                                }
                            }
                        };

                        if (row.has_batch_no && allocs.length) {
                            // One Stock Entry row per batch, since a row carries
                            // a single batch. Serials are split to match.
                            var cursor = 0;
                            allocs.forEach(function(b) {
                                var q = flt(b.qty);
                                var chunk = row.has_serial_no ? serials.slice(cursor, cursor + q) : null;
                                cursor += q;
                                add_row(q, b.batch_no, chunk);
                            });
                        } else if (row.has_serial_no) {
                            add_row(flt(row.qty), null, serials);
                        } else {
                            add_row(flt(row.qty), null, null);
                        }
                    });

                    frappe.set_route('Form', 'Stock Entry', se.name);

                    setTimeout(function() {
                        if (cur_frm && cur_frm.doc && cur_frm.doc.doctype === 'Stock Entry' && cur_frm.doc.name === se.name) {
                            if (project_name && !cur_frm.doc.custom_projects) {
                                cur_frm.set_value('custom_projects', project_name);
                            }
                            if (project_name && !cur_frm.doc.project) {
                                cur_frm.set_value('project', project_name);
                            }
                            cur_frm.refresh_fields();
                        }
                    }, 600);
                });
            }).addClass('btn-primary');
        }
    }
});

