frappe.ui.form.on('Installation', {
    refresh: function(frm) {
        if (frm.is_new()) {
            return;
        }

        frappe.db.count('Paper Work', { filters: { installation_id: frm.doc.name } }).then(function(n) {
            if (n) {
                frm.add_custom_button('View Paper Work', function() {
                    frappe.set_route('List', 'Paper Work', { installation_id: frm.doc.name });
                }, 'Create');
                return;
            }

            frm.add_custom_button('Paper Work', function() {
                frappe.model.with_doctype('Paper Work', function() {
                    var d = frappe.model.get_new_doc('Paper Work');

                    d.installation_id = frm.doc.name;
                    d.customer = frm.doc.customer;
                    d.company = frm.doc.company;
                    d.project = frm.doc.project;
                    d.completed_date = frm.doc.completed_date || frappe.datetime.get_today();
                    d.status = 'Pending';

                    var inst = frm.doc.name;
                    var cust = frm.doc.customer;
                    var proj = frm.doc.project;

                    frappe.set_route('Form', 'Paper Work', d.name);

                    setTimeout(function() {
                        if (cur_frm && cur_frm.doc && cur_frm.doc.doctype === 'Paper Work' && cur_frm.doc.name === d.name) {
                            if (!cur_frm.doc.installation_id) { cur_frm.set_value('installation_id', inst); }
                            if (cust && !cur_frm.doc.customer) { cur_frm.set_value('customer', cust); }
                            if (proj && !cur_frm.doc.project) { cur_frm.set_value('project', proj); }
                            cur_frm.refresh_fields();
                        }
                    }, 600);
                });
            }, 'Create');
        });
    }
});

frappe.ui.form.on("Customer", {
    refresh(frm) {
        if (frm.is_new()) return;
        setTimeout(() => load_dashboard(frm), 300);
    },
    onload_post_render(frm) {
        if (frm.is_new()) return;
        setTimeout(() => load_dashboard(frm), 500);
    }
});

/* =========================================================================
   STAGE CONFIG — hardcoded from actual doctype fields (no runtime guessing)
   ========================================================================= */

const WORK_STAGE_CONFIG = [
    { key: "quotation", no: 1, title: "Quotation", doctype: "Quotation", icon: "📝",
      optional: false, status_field: "status", done_statuses: ["Ordered", "Partially Ordered"] },

    { key: "loan", no: 2, title: "Loan", doctype: "Solar Loan", icon: "🏦",
      optional: true, customer_field: "customer", status_field: "status", done_statuses: ["Approved"] },

    { key: "site_visit", no: 3, title: "Site Visit", doctype: "Site Visit", icon: "📍",
      optional: false, customer_field: "customer", status_field: "status",
      assigned_field: "employee", done_statuses: ["Visited"] },

    { key: "sales_order", no: 4, title: "Sales Order", doctype: "Sales Order", icon: "🧾",
      optional: false, customer_field: "customer", status_field: "status", done_statuses: ["Completed", "Closed"] },

    { key: "project", no: 5, title: "Project", doctype: "Project", icon: "📁",
      optional: false, customer_field: "customer", status_field: "status",
      extra_fields: ["custom_total_cost"], done_statuses: ["Completed"] },

    { key: "product_delivery", no: 6, title: "Product Delivery", doctype: "Product Delivery", icon: "📦",
      optional: false, customer_field: "customer", status_field: "transfer_status", done_statuses: ["Transferred"] },

    { key: "installation", no: 7, title: "Installation", doctype: "Installation", icon: "🔧",
      optional: false, customer_field: "customer", status_field: "installation_status",
      assigned_field: "assigned_to", done_statuses: ["Completed"] },

    { key: "paperwork", no: 8, title: "Paperwork", doctype: "Paper Work", icon: "📄",
      optional: false, customer_field: "customer", status_field: "status", done_statuses: ["Completed"] },

    { key: "subsidy", no: 9, title: "Subsidy", doctype: "Subsidy", icon: "💰",
      optional: false, customer_field: "customer", status_field: "status", done_statuses: ["Sanctioned"] },

    { key: "kseb", no: 10, title: "KSEB Paperwork", doctype: "KSEB Paper Works", icon: "⚡",
      optional: false, customer_field: "customer", status_field: "status_of_kseb_paper_work", done_statuses: ["Completed"] },

    { key: "project_commission", no: 11, title: "Project Commission", doctype: "Project Commission", icon: "🏅",
      optional: false, customer_field: "customer", status_field: "status_of_project_commission", done_statuses: ["Commissioned"] }
];

/* =========================================================================
   LOAD
   ========================================================================= */

async function load_dashboard(frm) {
    const html_field = frm.fields_dict["custom_customer_work_stage"];
    if (!html_field) return;

    const customer = frm.doc.name;
    const stage_data = {};

    for (const stage of WORK_STAGE_CONFIG) {
        stage_data[stage.key] = stage.key === "quotation"
            ? await fetch_quotation(customer)
            : await fetch_stage(stage, customer);
    }

    // Project Cost, reusing the Project stage record
    const project_data = stage_data.project;
    const project_cost = (project_data && project_data.exists && project_data.custom_total_cost != null)
        ? project_data.custom_total_cost
        : null;

    // Current stage = the existing record with the most recent `modified` timestamp
    let current_stage = null;
    let current_data = null;
    let latest_modified = null;

    WORK_STAGE_CONFIG.forEach(stage => {
        const data = stage_data[stage.key];
        if (!data || !data.exists || !data.modified) return;
        const modified = new Date(data.modified);
        if (latest_modified === null || modified > latest_modified) {
            latest_modified = modified;
            current_stage = stage;
            current_data = data;
        }
    });

    render_dashboard(frm, html_field, {
        stages: WORK_STAGE_CONFIG,
        stage_data,
        current_stage,
        current_data,
        project_cost,
        customer
    });
}

/* =========================================================================
   FETCHERS
   ========================================================================= */

async function fetch_quotation(customer) {
    try {
        const records = await frappe.db.get_list("Quotation", {
            filters: { party_name: customer, quotation_to: "Customer" },
            fields: ["name", "status", "creation", "modified", "owner"],
            order_by: "creation desc",
            limit: 1
        });
        if (!records || !records.length) return { exists: false };
        const r = records[0];
        return { exists: true, name: r.name, status: r.status, creation: r.creation, modified: r.modified, owner: r.owner };
    } catch (e) {
        console.log("Quotation lookup failed", e);
        return { exists: false };
    }
}

async function fetch_stage(stage, customer) {
    try {
        let fields = ["name", "creation", "modified", "owner"];
        if (stage.status_field) fields.push(stage.status_field);
        if (stage.assigned_field) fields.push(stage.assigned_field);
        if (stage.extra_fields) fields = fields.concat(stage.extra_fields);

        const filters = {};
        filters[stage.customer_field] = customer;

        const records = await frappe.db.get_list(stage.doctype, {
            filters, fields, order_by: "creation desc", limit: 1
        });

        if (!records || !records.length) return { exists: false };
        const r = records[0];

        const result = {
            exists: true,
            name: r.name,
            creation: r.creation,
            modified: r.modified,
            owner: r.owner,
            status: stage.status_field ? (r[stage.status_field] || "") : "",
            assigned_to: stage.assigned_field ? (r[stage.assigned_field] || "") : ""
        };
        if (stage.extra_fields) stage.extra_fields.forEach(f => result[f] = r[f]);
        return result;

    } catch (e) {
        console.log("Error loading " + stage.doctype, e);
        return { exists: false };
    }
}

/* =========================================================================
   STATUS → COLOR CATEGORY
   ========================================================================= */

function get_stage_category(stage, data) {
    if (!data || !data.exists) return "none";
    const raw = (data.status || "").toString().trim().toLowerCase();
    const done = (stage.done_statuses || []).map(s => s.toLowerCase());
    return done.includes(raw) ? "green" : "blue";
}

function get_display_status(status) {
    if (!status || String(status).trim() === "") return "Pending";
    const value = String(status).trim();
    const map = {
        "processing": "Processing",
        "On hold": "On Hold"
    };
    return map[value] || value;
}

/* =========================================================================
   FORMAT HELPERS
   ========================================================================= */

function format_dt(value) {
    if (!value) return "—";
    try { return frappe.datetime.str_to_user(value); } catch (e) { return value; }
}

function format_money(value) {
    if (value === null || value === undefined || value === "") return "—";
    try { return frappe.format(value, { fieldtype: "Currency" }); } catch (e) { return value; }
}

function escape_html(value) {
    if (value === null || value === undefined) return "";
    return String(value)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

/* =========================================================================
   RENDER
   ========================================================================= */

function render_dashboard(frm, html_field, ctx) {
    const { stages, stage_data, current_stage, current_data, project_cost, customer } = ctx;

    const header_html = `
        <div class="cws-header">
            <div class="cws-header-title">
                <div class="cws-main-title">Customer Work Stage</div>
                <div class="cws-subtitle">Track the complete project lifecycle for this customer.</div>
            </div>
            <div class="cws-header-item">
                <div class="cws-label">Current Stage</div>
                <div class="cws-current-stage">
                    <span class="cws-dot cws-dot-${current_stage ? get_stage_category(current_stage, current_data) : 'none'}"></span>
                    ${current_stage ? escape_html(current_stage.title) : "Not Started"}
                </div>
            </div>
            <div class="cws-header-item">
                <div class="cws-label">Customer</div>
                <div class="cws-value">${escape_html(customer)}</div>
            </div>
            <div class="cws-header-item">
                <div class="cws-label">Project Cost</div>
                <div class="cws-value cws-cost" ${stage_data.project.exists ? `data-record-doctype="Project" data-record-name="${escape_html(stage_data.project.name)}"` : ""}>
                    ${format_money(project_cost)}
                </div>
            </div>
            <div class="cws-header-item">
                <div class="cws-label">Last Updated</div>
                <div class="cws-value">${current_data ? format_dt(current_data.modified) : "—"}</div>
            </div>
        </div>
    `;

    let workflow_html = `<div class="cws-workflow"><div class="cws-row">`;
    stages.slice(0, 6).forEach((stage, i) => {
        workflow_html += create_stage_card(stage, stage_data[stage.key], current_stage);
        if (i < 5) workflow_html += `<div class="cws-arrow">→</div>`;
    });
    workflow_html += `</div><div class="cws-row cws-row-bottom">`;
    stages.slice(6).forEach((stage, i) => {
        workflow_html += create_stage_card(stage, stage_data[stage.key], current_stage);
        if (i < 4) workflow_html += `<div class="cws-arrow">→</div>`;
    });
    workflow_html += `</div></div>`;

    const detail_status = current_data ? get_display_status(current_data.status) : "—";
    const detail_category = current_stage ? get_stage_category(current_stage, current_data) : "none";

    let lower_html = `
        <div class="cws-bottom-grid">
            <div class="cws-panel">
                <div class="cws-panel-title"><span class="cws-title-icon">◉</span> Stage Details</div>
                <div class="cws-detail-body">
                    <div class="cws-detail-row"><span>Current Stage</span><strong>${current_stage ? escape_html(current_stage.title) : "—"}</strong></div>
                    <div class="cws-detail-row"><span>Status</span><strong class="cws-status-pill cws-status-${detail_category}">${escape_html(detail_status)}</strong></div>
                    <div class="cws-detail-row"><span>Started On</span><strong>${current_data ? format_dt(current_data.creation) : "—"}</strong></div>
                    <div class="cws-detail-row"><span>Assigned To</span><strong>${current_data && current_data.assigned_to ? escape_html(current_data.assigned_to) : "—"}</strong></div>
                    <div class="cws-detail-row"><span>Record</span><strong>${current_data ? escape_html(current_data.name) : "—"}</strong></div>
                </div>
            </div>
            <div class="cws-panel">
                <div class="cws-panel-title"><span class="cws-title-icon">☰</span> Recent Activities</div>
                <div class="cws-activity-table">
                    <div class="cws-activity-head"><div>#</div><div>Activity</div><div>Date &amp; Time</div><div>By</div></div>
    `;

    let activities = stages
        .map(stage => ({ stage, data: stage_data[stage.key] }))
        .filter(a => a.data && a.data.exists && a.data.modified)
        .sort((a, b) => new Date(b.data.modified) - new Date(a.data.modified))
        .slice(0, 5);

    if (activities.length === 0) {
        lower_html += `<div class="cws-no-activity">No workflow activities yet.</div>`;
    } else {
        activities.forEach((a, i) => {
            const cat = get_stage_category(a.stage, a.data);
            lower_html += `
                <div class="cws-activity-row" data-record-doctype="${escape_html(a.stage.doctype)}" data-record-name="${escape_html(a.data.name)}">
                    <div>${i + 1}</div>
                    <div class="cws-activity-name"><span class="cws-dot cws-dot-${cat}"></span>${escape_html(a.stage.title)} — ${escape_html(get_display_status(a.data.status))}</div>
                    <div>${format_dt(a.data.modified)}</div>
                    <div>${a.data.owner ? escape_html(a.data.owner) : "—"}</div>
                </div>
            `;
        });
    }

    lower_html += `</div></div></div>`;

    const final_html = `
        <style>${DASHBOARD_CSS}</style>
        <div class="cws-container">${header_html}${workflow_html}${lower_html}</div>
    `;

    html_field.$wrapper.html(final_html);

    // Card clicks
    html_field.$wrapper.find(".cws-stage-card").on("click", function () {
        const key = $(this).attr("data-stage-key");
        const stage = stages.find(s => s.key === key);
        const data = stage_data[key];
        if (data && data.exists && data.name) {
            frappe.set_route("Form", stage.doctype, data.name);
            return;
        }
        if (stage.optional) {
            frappe.msgprint({ title: stage.title, message: `No ${stage.title} record has been created for this customer.`, indicator: "orange" });
            return;
        }
        frappe.msgprint({ title: stage.title, message: `No ${stage.title} record is linked to this customer yet.`, indicator: "blue" });
    });

    // Activity row + project cost clicks
    html_field.$wrapper.find(".cws-activity-row, .cws-cost[data-record-name]").on("click", function () {
        const dt = $(this).attr("data-record-doctype");
        const dn = $(this).attr("data-record-name");
        if (dt && dn) frappe.set_route("Form", dt, dn);
    });
}

function create_stage_card(stage, data, current_stage) {
    const category = get_stage_category(stage, data);
    const is_current = current_stage && current_stage.key === stage.key;
    const exists = data && data.exists;

    let status_text;
    if (exists) {
        status_text = get_display_status(data.status);
    } else {
        status_text = stage.optional ? "Not Applicable" : "Not Created";
    }

    let card_class = "cws-stage-card cws-cat-" + category;
    if (!exists && stage.optional) card_class += " cws-skipped";
    if (is_current) card_class += " cws-current";

    const optional_html = stage.optional ? `<div class="cws-badge cws-badge-optional">Optional</div>` : "";
    const current_html = is_current ? `<div class="cws-badge cws-badge-current">Current</div>` : "";
    const date_html = exists && data.creation ? `<div class="cws-stage-date">${format_dt(data.creation)}</div>` : "";

    return `
        <div class="${card_class}" data-stage-key="${stage.key}" title="Open ${escape_html(stage.title)}">
            ${optional_html}${current_html}
            <div class="cws-stage-icon">${stage.icon}</div>
            <div class="cws-stage-number">${stage.no}. ${escape_html(stage.title)}</div>
            <div class="cws-stage-status">${escape_html(status_text)}</div>
            ${date_html}
        </div>
    `;
}

