function render_payment_summary(frm) {
    var field = frm.get_field('custom_payment_summary');
    if (!field) { return; }

    var cur = frappe.defaults.get_default('currency') || 'INR';
    var money = function(v) { return format_currency(flt(v), cur); };

    field.$wrapper.html(
        '<div class="cps-card"><div class="cps-head">Payments</div>' +
        '<div class="cps-body">Loading\u2026</div></div>' +
        '<style>' +
        '.cps-card { border:1px solid var(--border-color,#e5e7eb); border-radius:10px; background:var(--card-bg,#fff); overflow:hidden; margin-top:14px; }' +
        '.cps-head { padding:12px 16px; border-bottom:1px solid var(--border-color,#e5e7eb); font-weight:600; font-size:13px; }' +
        '.cps-body { padding:16px; }' +
        '.cps-tiles { display:flex; gap:12px; flex-wrap:wrap; }' +
        '.cps-tile { flex:1; min-width:150px; border-radius:8px; padding:14px 16px; border:1px solid transparent; }' +
        '.cps-tile-label { font-size:11px; font-weight:500; opacity:0.85; }' +
        '.cps-tile-val { font-size:20px; font-weight:700; margin-top:3px; }' +
        '.cps-total { background:#f3f4f6; color:#374151; border-color:#e5e7eb; }' +
        '.cps-paid { background:#f0fdf4; color:#15803d; border-color:#bbf7d0; }' +
        '.cps-due { background:#fff7ed; color:#c2410c; border-color:#fed7aa; }' +
        '.cps-clear { background:#f0fdf4; color:#15803d; border-color:#bbf7d0; }' +
        '.cps-bar { height:6px; border-radius:99px; background:#e5e7eb; margin-top:14px; overflow:hidden; }' +
        '.cps-bar-fill { height:100%; background:#16a34a; }' +
        '.cps-note { font-size:11px; color:var(--text-muted,#6b7280); margin-top:8px; }' +
        '.cps-list { width:100%; margin-top:14px; font-size:12px; border-collapse:collapse; }' +
        '.cps-list th { text-align:left; font-weight:600; color:var(--text-muted,#6b7280); padding:6px 8px; border-bottom:1px solid var(--border-color,#e5e7eb); }' +
        '.cps-list td { padding:6px 8px; border-bottom:1px solid var(--border-color,#f3f4f6); }' +
        '.cps-list td.r, .cps-list th.r { text-align:right; }' +
        '.cps-empty { font-size:12px; color:var(--text-muted,#9ca3af); }' +
        '</style>'
    );

    var orders = frappe.db.get_list('Sales Order', {
        filters: { customer: frm.doc.name, docstatus: 1 },
        fields: ['name', 'grand_total'],
        limit: 500
    });

    var payments = frappe.db.get_list('Payment Entry', {
        filters: { party_type: 'Customer', party: frm.doc.name, docstatus: 1, payment_type: 'Receive' },
        fields: ['name', 'posting_date', 'paid_amount', 'mode_of_payment', 'reference_no'],
        order_by: 'posting_date desc',
        limit: 50
    });

    Promise.all([orders, payments]).then(function(res) {
        var so = res[0] || [];
        var pe = res[1] || [];

        var total = 0;
        so.forEach(function(r) { total += flt(r.grand_total); });

        var paid = 0;
        pe.forEach(function(r) { paid += flt(r.paid_amount); });

        var balance = total - paid;
        var pct = total > 0 ? Math.min(100, (paid / total) * 100) : 0;
        var settled = total > 0 && balance <= 0.005;

        var rows = '';
        if (pe.length) {
            rows = '<table class="cps-list"><thead><tr>' +
                   '<th>Date</th><th>Payment</th><th>Mode</th><th>Reference</th><th class="r">Amount</th>' +
                   '</tr></thead><tbody>' +
                   pe.map(function(p) {
                       return '<tr>' +
                              '<td>' + frappe.datetime.str_to_user(p.posting_date) + '</td>' +
                              '<td><a href="/app/payment-entry/' + encodeURIComponent(p.name) + '">' + p.name + '</a></td>' +
                              '<td>' + (p.mode_of_payment || '\u2014') + '</td>' +
                              '<td>' + (p.reference_no || '\u2014') + '</td>' +
                              '<td class="r">' + money(p.paid_amount) + '</td>' +
                              '</tr>';
                   }).join('') +
                   '</tbody></table>';
        } else {
            rows = '<div class="cps-empty" style="margin-top:14px">No payments received yet.</div>';
        }

        var html =
            '<div class="cps-tiles">' +
              '<div class="cps-tile cps-total">' +
                '<div class="cps-tile-label">Order Value</div>' +
                '<div class="cps-tile-val">' + money(total) + '</div></div>' +
              '<div class="cps-tile cps-paid">' +
                '<div class="cps-tile-label">Paid</div>' +
                '<div class="cps-tile-val">' + money(paid) + '</div></div>' +
              '<div class="cps-tile ' + (settled ? 'cps-clear' : 'cps-due') + '">' +
                '<div class="cps-tile-label">' + (settled ? 'Fully Paid' : 'Balance') + '</div>' +
                '<div class="cps-tile-val">' + money(balance > 0 ? balance : 0) + '</div></div>' +
            '</div>' +
            '<div class="cps-bar"><div class="cps-bar-fill" style="width:' + pct.toFixed(1) + '%"></div></div>' +
            '<div class="cps-note">' + pct.toFixed(0) + '% collected across ' + so.length + ' submitted sales order(s).</div>' +
            rows;

        field.$wrapper.find('.cps-body').html(html);
    }).catch(function() {
        field.$wrapper.find('.cps-body').html('<div class="cps-empty">Could not load payment data.</div>');
    });
}

