function render_previews(frm) {
    var field = frm.get_field('custom_document_previews');
    if (!field) { return; }

    var css =
        '<style>' +
        '.docprev { display:flex; gap:14px; flex-wrap:wrap; margin-top:6px; }' +
        '.docprev-item { width:190px; border:1px solid var(--border-color,#e5e7eb); border-radius:10px; overflow:hidden; background:var(--card-bg,#fff); }' +
        '.docprev-img { width:100%; height:130px; object-fit:cover; display:block; background:#f3f4f6; cursor:pointer; }' +
        '.docprev-file { height:130px; display:flex; align-items:center; justify-content:center; background:#f9fafb; color:#6b7280; font-size:12px; text-decoration:none; }' +
        '.docprev-cap { padding:8px 10px; font-size:11px; }' +
        '.docprev-cap b { display:block; font-size:12px; margin-bottom:2px; }' +
        '.docprev-cap a { color:var(--text-muted,#6b7280); word-break:break-all; }' +
        '.docprev-empty { font-size:12px; color:var(--text-muted,#9ca3af); }' +
        '</style>';

    var items = [];

    PREVIEW_FIELDS.forEach(function(f) {
        var url = frm.doc[f.field];
        if (!url) { return; }

        var lower = String(url).toLowerCase().split('?')[0];
        var is_img = /\.(png|jpe?g|gif|webp|bmp|svg)$/.test(lower);
        var safe = encodeURI(url);

        var body = is_img
            ? '<img class="docprev-img" src="' + safe + '" onclick="window.open(\'' + safe + '\', \'_blank\')">'
            : '<a class="docprev-file" href="' + safe + '" target="_blank">Open file</a>';

        items.push(
            '<div class="docprev-item">' + body +
            '<div class="docprev-cap"><b>' + f.label + '</b>' +
            '<a href="' + safe + '" target="_blank">' + url.split('/').pop() + '</a></div></div>'
        );
    });

    if (!items.length) {
        field.$wrapper.html(css + '<div class="docprev-empty">Attach a file above to see a preview here.</div>');
        return;
    }

    field.$wrapper.html(css + '<div class="docprev">' + items.join('') + '</div>');
}

