function render_attachments(frm) {
    var field = frm.get_field('custom_attachment_gallery');
    if (!field) { return; }

    var css =
        '<style>' +
        '.catt-card { border:1px solid var(--border-color,#e5e7eb); border-radius:10px; background:var(--card-bg,#fff); overflow:hidden; margin-top:14px; }' +
        '.catt-head { padding:12px 16px; border-bottom:1px solid var(--border-color,#e5e7eb); font-weight:600; font-size:13px; display:flex; justify-content:space-between; }' +
        '.catt-count { font-weight:500; color:var(--text-muted,#6b7280); }' +
        '.catt-body { padding:16px; }' +
        '.catt-group { margin-bottom:18px; }' +
        '.catt-group:last-child { margin-bottom:0; }' +
        '.catt-group-title { font-size:11px; font-weight:600; text-transform:uppercase; letter-spacing:0.04em; color:var(--text-muted,#6b7280); margin-bottom:8px; }' +
        '.catt-grid { display:flex; gap:12px; flex-wrap:wrap; }' +
        '.catt-item { width:150px; border:1px solid var(--border-color,#e5e7eb); border-radius:8px; overflow:hidden; }' +
        '.catt-img { width:100%; height:100px; object-fit:cover; display:block; background:#f3f4f6; cursor:pointer; }' +
        '.catt-file { height:100px; display:flex; align-items:center; justify-content:center; background:#f9fafb; color:#6b7280; font-size:11px; text-decoration:none; }' +
        '.catt-cap { padding:7px 9px; font-size:10.5px; line-height:1.35; }' +
        '.catt-cap b { display:block; font-size:11px; word-break:break-all; margin-bottom:2px; }' +
        '.catt-cap a { color:var(--text-muted,#6b7280); }' +
        '.catt-empty { font-size:12px; color:var(--text-muted,#9ca3af); }' +
        '</style>';

    field.$wrapper.html(css +
        '<div class="catt-card"><div class="catt-head"><span>Attachments</span></div>' +
        '<div class="catt-body catt-empty">Loading\u2026</div></div>');

    var lookups = SOURCES.map(function(src) {
        var f = {};
        f[src.field] = frm.doc.name;
        return frappe.db.get_list(src.dt, { filters: f, fields: ['name'], limit: 200 })
            .then(function(rows) {
                return { dt: src.dt, names: (rows || []).map(function(r) { return r.name; }) };
            })
            .catch(function() { return { dt: src.dt, names: [] }; });
    });

    Promise.all(lookups).then(function(groups) {
        var pairs = [];
        var all_names = [];
        groups.forEach(function(g) {
            if (g.names.length) {
                pairs.push(g);
                all_names = all_names.concat(g.names);
            }
        });

        all_names.push(frm.doc.name);
        var dts = pairs.map(function(g) { return g.dt; });
        dts.push('Customer');

        if (!all_names.length) {
            field.$wrapper.find('.catt-body').html('No related documents yet.');
            return;
        }

        return frappe.db.get_list('File', {
            filters: {
                attached_to_doctype: ['in', dts],
                attached_to_name: ['in', all_names]
            },
            fields: ['name', 'file_name', 'file_url', 'attached_to_doctype', 'attached_to_name', 'creation'],
            order_by: 'creation desc',
            limit: 300
        }).then(function(files) {
            files = files || [];
            if (!files.length) {
                field.$wrapper.find('.catt-body').html('No attachments uploaded yet.');
                return;
            }

            var by_dt = {};
            files.forEach(function(f) {
                var k = f.attached_to_doctype || 'Other';
                if (!by_dt[k]) { by_dt[k] = []; }
                by_dt[k].push(f);
            });

            var order = ['Customer'].concat(SOURCES.map(function(s) { return s.dt; }));
            var html = '';

            order.forEach(function(dt) {
                var list = by_dt[dt];
                if (!list || !list.length) { return; }

                html += '<div class="catt-group"><div class="catt-group-title">' + dt + ' (' + list.length + ')</div><div class="catt-grid">';

                list.forEach(function(f) {
                    var url = f.file_url || '';
                    var lower = url.toLowerCase().split('?')[0];
                    var is_img = /\.(png|jpe?g|gif|webp|bmp|svg)$/.test(lower);
                    var safe = encodeURI(url);
                    var body = is_img
                        ? '<img class="catt-img" src="' + safe + '" onclick="window.open(\'' + safe + '\',\'_blank\')">'
                        : '<a class="catt-file" href="' + safe + '" target="_blank">Open file</a>';

                    html += '<div class="catt-item">' + body +
                            '<div class="catt-cap"><b>' + (f.file_name || 'file') + '</b>' +
                            '<a href="/app/' + frappe.router.slug(dt) + '/' + encodeURIComponent(f.attached_to_name) + '">' +
                            f.attached_to_name + '</a></div></div>';
                });

                html += '</div></div>';
            });

            field.$wrapper.find('.catt-head').append('<span class="catt-count">' + files.length + ' file(s)</span>');
            field.$wrapper.find('.catt-body').removeClass('catt-empty').html(html);
        });
    }).catch(function() {
        field.$wrapper.find('.catt-body').html('Could not load attachments.');
    });
}

