function fill_default_checks(frm) {
    if ((frm.doc.commissioning_checklist || []).length) { return; }
    DEFAULT_CHECKS.forEach(function(row) {
        var d = frm.add_child('commissioning_checklist');
        d.category = row[0];
        d.check_item = row[1];
        d.is_required = row[2];
        d.status = 'Pending';
    });
    frm.refresh_field('commissioning_checklist');
}

function summarise_checks(frm) {
    var rows = frm.doc.commissioning_checklist || [];
    var required = rows.filter(function(r) { return r.is_required; });
    var cleared = required.filter(function(r) { return r.status === 'OK' || r.status === 'Not Applicable'; });
    var failed = rows.filter(function(r) { return r.status === 'Not OK'; });

    var txt = cleared.length + ' of ' + required.length + ' required checks cleared';
    if (failed.length) { txt += '  \u2022  ' + failed.length + ' marked Not OK'; }
    frm.set_value('checks_summary', txt);
}

