var CC_STATES = [
    { key: 'Pending',        label: 'Pending',        cls: 'ccl-warn' },
    { key: 'OK',             label: 'OK',             cls: 'ccl-good' },
    { key: 'Not OK',         label: 'Not OK',         cls: 'ccl-bad'  },
    { key: 'Not Applicable', label: 'Not Applicable', cls: 'ccl-idle' }
];

function cc_css() {
    return '<style>' +
    '.ccl-card { border:1px solid var(--border-color,#e5e7eb); border-radius:10px; background:var(--card-bg,#fff); overflow:hidden; margin-top:14px; }' +
    '.ccl-head { padding:12px 16px; border-bottom:1px solid var(--border-color,#e5e7eb); font-weight:600; font-size:13px; }' +
    '.ccl-body { padding:16px; }' +
    '.ccl-tabs { display:flex; gap:8px; flex-wrap:wrap; margin-bottom:14px; }' +
    '.ccl-tab { border:1px solid var(--border-color,#e5e7eb); border-radius:99px; padding:5px 13px; font-size:12px; cursor:pointer; background:#fff; display:flex; align-items:center; gap:7px; }' +
    '.ccl-tab:hover { background:#f9fafb; }' +
    '.ccl-tab.active { border-color:#111; font-weight:600; }' +
    '.ccl-pill { border-radius:99px; padding:1px 7px; font-size:11px; font-weight:600; }' +
    '.ccl-warn .ccl-pill { background:#fff7ed; color:#c2410c; }' +
    '.ccl-good .ccl-pill { background:#f0fdf4; color:#15803d; }' +
    '.ccl-bad .ccl-pill  { background:#fef2f2; color:#b91c1c; }' +
    '.ccl-idle .ccl-pill { background:#f3f4f6; color:#4b5563; }' +
    '.ccl-table { width:100%; border-collapse:collapse; font-size:12px; }' +
    '.ccl-table th { text-align:left; font-weight:600; color:var(--text-muted,#6b7280); padding:6px 8px; border-bottom:1px solid var(--border-color,#e5e7eb); }' +
    '.ccl-table td { padding:7px 8px; border-bottom:1px solid var(--border-color,#f3f4f6); vertical-align:top; }' +
    '.ccl-cat { color:var(--text-muted,#6b7280); white-space:nowrap; }' +
    '.ccl-req { color:#c2410c; font-size:10px; margin-left:5px; }' +
    '.ccl-empty { font-size:12px; color:var(--text-muted,#9ca3af); padding:6px 0; }' +
    '.ccl-src { font-size:11px; color:var(--text-muted,#9ca3af); margin-top:10px; }' +
    '</style>';
}

function cc_render(field, rows, sources) {
    var counts = {};
    CC_STATES.forEach(function(s) {
        counts[s.key] = rows.filter(function(r) { return (r.status || 'Pending') === s.key; }).length;
    });

    var tabs = CC_STATES.map(function(s, i) {
        return '<div class="ccl-tab ' + s.cls + (i === 0 ? ' active' : '') + '" data-state="' + s.key + '">' +
               '<span>' + s.label + '</span><span class="ccl-pill">' + counts[s.key] + '</span></div>';
    }).join('');

    field.$wrapper.html(cc_css() +
        '<div class="ccl-card">' +
          '<div class="ccl-head">Commissioning Checklist</div>' +
          '<div class="ccl-body">' +
            '<div class="ccl-tabs">' + tabs + '</div>' +
            '<div class="ccl-list"></div>' +
            '<div class="ccl-src">From: ' + sources.join(', ') + '</div>' +
          '</div>' +
        '</div>');

    var draw = function(state) {
        var subset = rows.filter(function(r) { return (r.status || 'Pending') === state; });
        if (!subset.length) {
            field.$wrapper.find('.ccl-list').html('<div class="ccl-empty">No checks in this state.</div>');
            return;
        }
        var html = '<table class="ccl-table"><thead><tr>' +
                   '<th style="width:22%">Category</th><th>Check</th><th style="width:28%">Observation</th>' +
                   '</tr></thead><tbody>' +
                   subset.map(function(r) {
                       return '<tr>' +
                              '<td class="ccl-cat">' + (r.category || '\u2014') + '</td>' +
                              '<td>' + (r.check_item || '') +
                              (r.is_required ? '<span class="ccl-req">required</span>' : '') + '</td>' +
                              '<td>' + (r.observation || '\u2014') + '</td>' +
                              '</tr>';
                   }).join('') +
                   '</tbody></table>';
        field.$wrapper.find('.ccl-list').html(html);
    };

    field.$wrapper.find('.ccl-tab').on('click', function() {
        field.$wrapper.find('.ccl-tab').removeClass('active');
        $(this).addClass('active');
        draw($(this).data('state'));
    });

    draw('Pending');
}

function render_commissioning_checks(frm) {
    var field = frm.get_field('custom_commissioning_checks');
    if (!field) { return; }

    field.$wrapper.html(cc_css() +
        '<div class="ccl-card"><div class="ccl-head">Commissioning Checklist</div>' +
        '<div class="ccl-body ccl-empty">Loading\u2026</div></div>');

    frappe.db.get_list('Project Commission', {
        filters: { customer: frm.doc.name },
        fields: ['name'],
        limit: 10
    }).then(function(pcs) {
        pcs = pcs || [];
        if (!pcs.length) {
            field.$wrapper.find('.ccl-body').html('No Project Commission record for this customer yet.');
            return;
        }

        return Promise.all(pcs.map(function(p) {
            return frappe.db.get_doc('Project Commission', p.name);
        })).then(function(docs) {
            var rows = [];
            var sources = [];
            docs.forEach(function(d) {
                sources.push(d.name);
                (d.commissioning_checklist || []).forEach(function(r) { rows.push(r); });
            });

            if (!rows.length) {
                field.$wrapper.find('.ccl-body').html('No checklist rows recorded yet.');
                return;
            }
            cc_render(field, rows, sources);
        });
    }).catch(function() {
        field.$wrapper.find('.ccl-body').html('Could not load the commissioning checklist.');
    });
}

