        }
    }
});

// has_serial_no / has_batch_no / is_stock_item are fetch_from fields, so they
// only populate when the Item link is set. Rows saved before those fields
// existed would read 0 and be treated as service items. This resyncs them
// from the Item master on every load, without dirtying the form.

function pd_sync_item_flags(frm) {
    var rows = (frm.doc.items || []).filter(function(r) { return r.item_code; });
    if (!rows.length) { return; }

    var codes = [];
    rows.forEach(function(r) {
        if (codes.indexOf(r.item_code) === -1) { codes.push(r.item_code); }
    });

    frappe.db.get_list('Item', {
        filters: { name: ['in', codes] },
        fields: ['name', 'has_serial_no', 'has_batch_no', 'is_stock_item'],
        limit: 200
    }).then(function(items) {
        var by_code = {};
        (items || []).forEach(function(i) { by_code[i.name] = i; });

        var changed = false;
        rows.forEach(function(r) {
            var it = by_code[r.item_code];
            if (!it) { return; }
            ['has_serial_no', 'has_batch_no', 'is_stock_item'].forEach(function(f) {
                var v = cint(it[f]);
                if (cint(r[f]) !== v) { r[f] = v; changed = true; }
            });
        });

        if (changed) { frm.refresh_field('items'); }
    }).catch(function() { /* leave whatever is stored */ });
}

frappe.ui.form.on('Product Delivery', {
    onload: function(frm) { pd_sync_item_flags(frm); },
    refresh: function(frm) { pd_sync_item_flags(frm); },
    validate: function(frm) { pd_sync_item_flags(frm); }
});

// Mirrors the 'Serial No - Warranty Dates and Status' server script so expiry
// dates and statuses update as you type, rather than only appearing after save.
// The server script remains authoritative.

function sn_expiry_from(start, qty, unit) {
    if (!start || !qty || qty <= 0) { return null; }
    if (unit === 'Days')   { return frappe.datetime.add_days(start, qty); }
    if (unit === 'Months') { return frappe.datetime.add_months(start, qty); }
    return frappe.datetime.add_months(start, qty * 12);
}

function sn_status_for(start, expiry) {
    if (!start || !expiry) { return 'Not Started'; }
    return frappe.datetime.get_diff(expiry, frappe.datetime.get_today()) >= 0 ? 'Ongoing' : 'Expired';
}

// Used while editing - marks the form dirty, which is correct here.
function sn_recalc_warranty(frm) {
    var start = frm.doc.custom_consumed_date;
    var expiry = sn_expiry_from(start, cint(frm.doc.custom_warranty_period), frm.doc.custom_warranty_period_unit || 'Years');
    frm.set_value('warranty_expiry_date', expiry);
    frm.set_value('custom_warranty_status', sn_status_for(start, expiry));
}

function sn_recalc_amc(frm) {
    var start = frm.doc.custom_amc_start_date;
    var expiry = sn_expiry_from(start, cint(frm.doc.custom_amc_period), frm.doc.custom_amc_period_unit || 'Years');
    frm.set_value('amc_expiry_date', expiry);
    frm.set_value('custom_amc_status', sn_status_for(start, expiry));
}

// Used on load - cover can lapse between saves, so the displayed statuses are
// refreshed without dirtying the form.
function sn_refresh_status(frm) {
    var w = sn_status_for(frm.doc.custom_consumed_date, frm.doc.warranty_expiry_date);
    if (frm.doc.custom_warranty_status !== w) {
        frm.doc.custom_warranty_status = w;
        frm.refresh_field('custom_warranty_status');
    }

    var a = sn_status_for(frm.doc.custom_amc_start_date, frm.doc.amc_expiry_date);
    if (frm.doc.custom_amc_status !== a) {
        frm.doc.custom_amc_status = a;
        frm.refresh_field('custom_amc_status');
    }
}

